//! Bitcoin P2WPKH construction, cross-checked against bitcoinjs-lib.
//!
//! CLAUDE.md §7 requires the sighash to match an independent bitcoinjs-lib
//! fixture. `tests/fixtures/bitcoin.json` is generated by
//! `scripts/gen-btc-fixtures.mjs`, which shares no code with the Rust
//! implementation.
//!
//! The fixture also records the property the Bitcoin fee cap depends on: a
//! BIP143 sighash commits the input's amount, so a relayer that misreports a
//! UTXO value produces a signature that cannot be used.

mod common;

use keyring_contract::bitcoin::{
    build_spend, decode_hex, hash160, p2wpkh_script_from_address, p2wpkh_script_from_pubkey,
    BitcoinError, BitcoinParams, DUST_THRESHOLD,
};
use near_sdk::json_types::U128;
use near_sdk::serde_json;
use near_sdk::test_utils::VMContextBuilder;
use near_sdk::testing_env;

const FIXTURES: &str = include_str!("fixtures/bitcoin.json");

fn vm() {
    testing_env!(VMContextBuilder::new().build());
}

fn hex_of(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit(u32::from(b >> 4), 16).unwrap());
        s.push(char::from_digit(u32::from(b & 0x0f), 16).unwrap());
    }
    s
}

fn doc() -> serde_json::Value {
    serde_json::from_str(FIXTURES).expect("fixtures parse")
}

/// Rebuilds a fixture's spend through the contract's own builder.
fn spend_from(f: &serde_json::Value) -> keyring_contract::bitcoin::P2wpkhSpend {
    let input: u128 = f["input_value"].as_str().unwrap().parse().unwrap();
    let pay: u128 = f["pay_amount"].as_str().unwrap().parse().unwrap();
    let change: u128 = f["change_amount"]
        .as_str()
        .map(|c| c.parse().unwrap())
        .unwrap_or(0);
    // The builder sizes change from the requested fee, so derive that fee.
    let fee = input - pay - change;
    let params = BitcoinParams {
        txid: f["txid"].as_str().unwrap().to_string(),
        vout: f["vout"].as_u64().unwrap() as u32,
        input_value: U128(input),
        fee: U128(fee),
    };
    build_spend(
        &params,
        f["pay_to"].as_str().unwrap(),
        pay,
        Some(&f["keyring_pubkey"].as_str().unwrap().to_string()),
    )
    .expect("fixture spend builds")
}

// --------------------------------------------------- bitcoinjs cross-check

#[test]
fn every_sighash_matches_the_bitcoinjs_reference() {
    vm();
    let d = doc();
    let spends = d["spends"].as_array().expect("spends");
    assert!(!spends.is_empty());
    for f in spends {
        let name = f["name"].as_str().unwrap();
        let spend = spend_from(f);
        assert_eq!(
            hex_of(&spend.sighash()),
            f["sighash"].as_str().unwrap(),
            "{name}: BIP143 sighash differs from bitcoinjs-lib"
        );
    }
}

#[test]
fn the_script_code_matches_the_reference() {
    // The scriptCode for a P2WPKH input is the P2PKH script over the same key
    // hash, not the witness program. Easy to get wrong, so it is pinned.
    vm();
    let d = doc();
    let f = &d["spends"][0];
    let spend = spend_from(f);
    let expected_hash = f["keyring_hash160"].as_str().unwrap();
    assert_eq!(hex_of(&spend.key_hash), expected_hash);

    let preimage = spend.sighash_preimage();
    let script_code = decode_hex(f["script_code"].as_str().unwrap()).unwrap();
    assert!(
        preimage
            .windows(script_code.len())
            .any(|w| w == script_code.as_slice()),
        "the reference scriptCode must appear in the preimage"
    );
}

#[test]
fn addresses_decode_to_the_reference_script_pubkeys() {
    vm();
    let d = doc();
    for a in d["addresses"].as_array().unwrap() {
        let addr = a["address"].as_str().unwrap();
        match a["script_pubkey"].as_str() {
            Some(expected) => assert_eq!(
                p2wpkh_script_from_address(addr)
                    .map(|s| hex_of(&s))
                    .as_deref(),
                Some(expected),
                "{addr}: scriptPubKey differs from bitcoinjs-lib"
            ),
            // bitcoinjs rejected it, so we must too: a bad checksum or the
            // wrong network must never produce a payable script.
            None => assert!(
                p2wpkh_script_from_address(addr).is_none(),
                "{addr}: must be rejected, bitcoinjs-lib rejects it"
            ),
        }
    }
}

// ------------------------------------- the property the fee cap rests on

#[test]
fn the_sighash_commits_to_the_input_amount() {
    // If this ever stops holding, the Bitcoin fee cap stops being enforceable:
    // a relayer could understate a UTXO, have a small fee approved, and still
    // broadcast a transaction paying a large one. BIP143 prevents that by
    // committing the amount, so a misreported value yields a signature that
    // does not verify against the real UTXO.
    vm();
    let d = doc();
    let s = &d["amount_sensitivity"];
    let f = &d["spends"][0];

    let mut p = BitcoinParams {
        txid: f["txid"].as_str().unwrap().to_string(),
        vout: f["vout"].as_u64().unwrap() as u32,
        input_value: U128(s["input_value_a"].as_str().unwrap().parse().unwrap()),
        fee: U128(1_000),
    };
    let pay: u128 = f["pay_amount"].as_str().unwrap().parse().unwrap();
    let dest = f["pay_to"].as_str().unwrap();
    let key = f["keyring_pubkey"].as_str().unwrap().to_string();

    let a = build_spend(&p, dest, pay, Some(&key)).unwrap().sighash();
    p.input_value = U128(s["input_value_b"].as_str().unwrap().parse().unwrap());
    let b = build_spend(&p, dest, pay, Some(&key)).unwrap().sighash();

    assert_ne!(
        hex_of(&a),
        hex_of(&b),
        "one satoshi of difference in the claimed input must change the sighash"
    );
}

#[test]
fn the_fee_is_inputs_minus_outputs() {
    vm();
    let d = doc();
    let f = &d["spends"][0];
    let spend = spend_from(f);
    let input: u64 = f["input_value"].as_str().unwrap().parse().unwrap();
    let out: u64 = spend.outputs.iter().map(|o| o.value).sum();
    assert_eq!(spend.fee(), input - out);
}

// ------------------------------------------------------ output constraints

#[test]
fn there_are_never_more_than_a_payment_and_change() {
    // Invariant 8: outputs are exactly the approved payment plus change back
    // to the Keyring address. There is no field for a third output.
    vm();
    let d = doc();
    for f in d["spends"].as_array().unwrap() {
        let spend = spend_from(f);
        assert!(
            spend.outputs.len() <= 2,
            "{}: at most two outputs",
            f["name"].as_str().unwrap()
        );
        // The first output is always the payment, at the approved amount.
        let pay: u64 = f["pay_amount"].as_str().unwrap().parse().unwrap();
        assert_eq!(spend.outputs[0].value, pay);
        assert_eq!(
            hex_of(&spend.outputs[0].script_pubkey),
            hex_of(&p2wpkh_script_from_address(f["pay_to"].as_str().unwrap()).unwrap())
        );
    }
}

#[test]
fn change_goes_to_the_keyring_address_and_nowhere_else() {
    vm();
    let d = doc();
    let f = &d["spends"][0];
    let spend = spend_from(f);
    assert_eq!(spend.outputs.len(), 2);
    let expected =
        p2wpkh_script_from_pubkey(f["keyring_pubkey"].as_str().unwrap()).expect("valid key");
    assert_eq!(
        hex_of(&spend.outputs[1].script_pubkey),
        hex_of(&expected),
        "change must pay the Keyring's own derived address"
    );
}

#[test]
fn change_below_dust_is_omitted_and_becomes_fee() {
    vm();
    let params = BitcoinParams {
        txid: "00".repeat(32),
        vout: 0,
        input_value: U128(60_200),
        fee: U128(0),
    };
    let dest = doc()["spends"][0]["pay_to"].as_str().unwrap().to_string();
    let key = doc()["spends"][0]["keyring_pubkey"]
        .as_str()
        .unwrap()
        .to_string();
    let spend = build_spend(&params, &dest, 60_000, Some(&key)).unwrap();
    assert_eq!(spend.outputs.len(), 1, "dust change must be omitted");
    // The omitted change becomes fee, and that larger fee is what the cap is
    // checked against, so omitting change cannot sneak past the limit.
    assert_eq!(spend.fee(), 200);
    assert!(spend.fee() < DUST_THRESHOLD);
}

#[test]
fn change_exactly_at_the_dust_threshold_is_kept() {
    vm();
    let dest = doc()["spends"][0]["pay_to"].as_str().unwrap().to_string();
    let key = doc()["spends"][0]["keyring_pubkey"]
        .as_str()
        .unwrap()
        .to_string();
    let params = BitcoinParams {
        txid: "00".repeat(32),
        vout: 0,
        input_value: U128(10_000 + DUST_THRESHOLD as u128),
        fee: U128(0),
    };
    let spend = build_spend(&params, &dest, 10_000, Some(&key)).unwrap();
    assert_eq!(spend.outputs.len(), 2);
    assert_eq!(spend.outputs[1].value, DUST_THRESHOLD);
}

// ---------------------------------------------------------- rejected inputs

#[test]
fn a_spend_without_a_registered_keyring_key_is_refused() {
    // Change would otherwise have nowhere safe to go.
    vm();
    let params = BitcoinParams {
        txid: "00".repeat(32),
        vout: 0,
        input_value: U128(100_000),
        fee: U128(1_000),
    };
    let dest = doc()["spends"][0]["pay_to"].as_str().unwrap().to_string();
    assert_eq!(
        build_spend(&params, &dest, 10_000, None).unwrap_err(),
        BitcoinError::NoKeyringKey
    );
}

#[test]
fn an_input_too_small_for_the_payment_and_fee_is_refused() {
    vm();
    let dest = doc()["spends"][0]["pay_to"].as_str().unwrap().to_string();
    let key = doc()["spends"][0]["keyring_pubkey"]
        .as_str()
        .unwrap()
        .to_string();

    let params = BitcoinParams {
        txid: "00".repeat(32),
        vout: 0,
        input_value: U128(10_000),
        fee: U128(1_000),
    };
    assert_eq!(
        build_spend(&params, &dest, 10_000, Some(&key)).unwrap_err(),
        BitcoinError::InsufficientInput
    );
    assert_eq!(
        build_spend(&params, &dest, 20_000, Some(&key)).unwrap_err(),
        BitcoinError::PaymentExceedsInput
    );
}

#[test]
fn malformed_txids_and_keys_are_refused() {
    vm();
    let dest = doc()["spends"][0]["pay_to"].as_str().unwrap().to_string();
    let key = doc()["spends"][0]["keyring_pubkey"]
        .as_str()
        .unwrap()
        .to_string();
    let ok = BitcoinParams {
        txid: "00".repeat(32),
        vout: 0,
        input_value: U128(100_000),
        fee: U128(1_000),
    };

    let short = BitcoinParams {
        txid: "00".repeat(31),
        ..ok.clone()
    };
    assert_eq!(
        build_spend(&short, &dest, 10_000, Some(&key)).unwrap_err(),
        BitcoinError::InvalidTxid
    );

    let uncompressed = "04".to_string() + &"11".repeat(64);
    assert_eq!(
        build_spend(&ok, &dest, 10_000, Some(&uncompressed)).unwrap_err(),
        BitcoinError::InvalidKeyringAddress,
        "an uncompressed key would derive a different address"
    );

    assert_eq!(
        build_spend(&ok, "not-an-address", 10_000, Some(&key)).unwrap_err(),
        BitcoinError::InvalidDestination
    );
}

#[test]
fn bech32m_and_other_witness_versions_are_refused() {
    // Keyring builds P2WPKH spends only. A Taproot address uses bech32m and a
    // different witness version; accepting it would produce an unspendable or
    // wrong output.
    vm();
    for addr in [
        // Valid bech32m (witness v1) testnet address.
        "tb1pqqqqp399et2xygdj5xreqhjjvcmzhxw4aywxecjdzew6hylgvsesf3hn0c",
        // Mainnet P2WPKH.
        "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4",
    ] {
        assert!(
            p2wpkh_script_from_address(addr).is_none(),
            "{addr} must be refused"
        );
    }
}

#[test]
fn hash160_is_ripemd160_of_sha256() {
    vm();
    // Pinned against the known hash160 of the fixture's public key.
    let d = doc();
    let key = decode_hex(d["spends"][0]["keyring_pubkey"].as_str().unwrap()).unwrap();
    assert_eq!(
        hex_of(&hash160(&key)),
        d["spends"][0]["keyring_hash160"].as_str().unwrap()
    );
}

// ------------------------------------------- through the contract, end to end

use common::*;
use keyring_contract::policy::RefusalCode;
use keyring_contract::signer::SignerBackend;
use keyring_contract::state::RequestStatus;
use keyring_contract::types::{Asset, Chain, ChainParams};
use keyring_contract::{Contract, RequestOutcome};
use near_sdk::{PromiseOrValue, PublicKey};

const OWNER: &str = "owner.testnet";

fn ctx(predecessor: &str, signer_pk: PublicKey, now_ms: u64) {
    let mut b = VMContextBuilder::new();
    b.current_account_id(account("keyring.testnet"))
        .predecessor_account_id(account(predecessor))
        .signer_account_id(account(predecessor))
        .signer_account_pk(signer_pk)
        .block_timestamp(now_ms * 1_000_000);
    testing_env!(b.build());
}

/// A contract with a Bitcoin-capable agent whose BTC key is registered.
fn btc_setup(register_key: bool) -> Contract {
    ctx(OWNER, pk(0), at_utc(12, 0));
    let mut c = Contract::new(SignerBackend::Mock);
    c.register_keyring();
    c.register_agent(pk(1), "agent-one".to_string(), btc_policy());
    if register_key {
        c.set_agent_btc_pubkey(pk(1), BTC_PUBKEY.to_string());
    }
    c
}

fn btc_request(c: &mut Contract, amount: u128, fee: u128, key: &str) -> RequestOutcome {
    ctx("agent-host.testnet", pk(1), at_utc(12, 0));
    match c.request_transfer(
        Chain::BitcoinTestnet4,
        Asset::Native,
        BTC_DEST.to_string(),
        U128(amount),
        btc_params(fee),
        key.to_string(),
    ) {
        PromiseOrValue::Value(o) => o,
        PromiseOrValue::Promise(_) => panic!("mock backend resolves synchronously"),
    }
}

#[test]
fn a_bitcoin_spend_signs_the_independently_computed_sighash() {
    let mut c = btc_setup(true);
    let out = btc_request(&mut c, 60_000, 1_000, "btc-1");
    assert!(matches!(out, RequestOutcome::Signed { .. }), "got {out:?}");

    let req = c.get_request(1).expect("recorded");
    assert_eq!(req.status, RequestStatus::Signed);
    assert_eq!(req.fee, U128(1_000), "the fee is derived, not supplied");

    // Rebuild the spend here and confirm the contract signed that exact hash.
    let params = BitcoinParams {
        txid: "7f3e2a1b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f7".to_string(),
        vout: 1,
        input_value: U128(100_000),
        fee: U128(1_000),
    };
    let expected = build_spend(&params, BTC_DEST, 60_000, Some(&BTC_PUBKEY.to_string()))
        .expect("builds")
        .sighash();
    assert_eq!(req.payload_hex, Some(hex_of(&expected)));
}

#[test]
#[should_panic(expected = "no Bitcoin public key is registered")]
fn a_bitcoin_spend_without_a_registered_key_is_refused() {
    // Change would otherwise have to go somewhere the contract cannot verify.
    let mut c = btc_setup(false);
    btc_request(&mut c, 60_000, 1_000, "btc-1");
}

#[test]
fn the_bitcoin_fee_cap_is_enforced_against_the_derived_fee() {
    let mut c = btc_setup(true);
    // 5000 sat is the cap; 5001 must be refused.
    let out = btc_request(&mut c, 60_000, 5_001, "btc-over");
    match out {
        RequestOutcome::Refused { refusal, .. } => {
            assert_eq!(refusal.code, RefusalCode::FeeCapExceeded);
            assert_eq!(refusal.limit, Some(U128(5_000)));
            assert_eq!(refusal.observed, Some(U128(5_001)));
        }
        other => panic!("expected a fee refusal, got {other:?}"),
    }
    // Exactly at the cap is allowed.
    assert!(matches!(
        btc_request(&mut c, 60_000, 5_000, "btc-at"),
        RequestOutcome::Signed { .. }
    ));
}

#[test]
fn dropping_dust_change_cannot_sneak_a_fee_past_the_cap() {
    // The subtle case. Requesting a fee just under the cap, on an input that
    // leaves change below the dust threshold, means the change output is
    // dropped and the whole remainder becomes fee. Policy must be shown that
    // larger number, not the one that was requested.
    //
    // input 75_200 - payment 70_000 = 5_200 remainder. A requested fee of
    // 5_000 leaves 200 sat of change, which is dust, so the transaction really
    // pays 5_200 — one step over the 5_000 cap.
    let mut c = btc_setup(true);
    ctx("agent-host.testnet", pk(1), at_utc(12, 0));
    let params = ChainParams::Bitcoin(BitcoinParams {
        txid: "7f3e2a1b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f7".to_string(),
        vout: 1,
        input_value: U128(75_200),
        fee: U128(5_000),
    });
    let out = c.request_transfer(
        Chain::BitcoinTestnet4,
        Asset::Native,
        BTC_DEST.to_string(),
        U128(70_000),
        params,
        "btc-dust".to_string(),
    );
    match out {
        PromiseOrValue::Value(RequestOutcome::Refused { refusal, .. }) => {
            assert_eq!(refusal.code, RefusalCode::FeeCapExceeded);
            // The real fee, not the 5_000 that was asked for.
            assert_eq!(refusal.observed, Some(U128(5_200)));
        }
        _ => panic!("the real fee, including dropped dust, must be what is checked"),
    }
}

#[test]
fn bitcoin_policy_rules_still_apply() {
    let mut c = btc_setup(true);
    // Per-request cap is 70k sat.
    assert!(matches!(
        btc_request(&mut c, 70_001, 1_000, "over"),
        RequestOutcome::Refused { .. }
    ));
    // An unallowlisted destination is refused.
    ctx("agent-host.testnet", pk(1), at_utc(12, 0));
    let out = c.request_transfer(
        Chain::BitcoinTestnet4,
        Asset::Native,
        "tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx".to_string(),
        U128(1_000),
        btc_params(1_000),
        "wrong-dest".to_string(),
    );
    match out {
        PromiseOrValue::Value(RequestOutcome::Refused { refusal, .. }) => {
            assert_eq!(refusal.code, RefusalCode::DestinationNotAllowed);
        }
        _ => panic!("an unallowlisted Bitcoin destination must be refused"),
    }
}

#[test]
#[should_panic(expected = "do not match the requested chain")]
fn evm_parameters_are_rejected_for_a_bitcoin_request() {
    let mut c = btc_setup(true);
    ctx("agent-host.testnet", pk(1), at_utc(12, 0));
    let _ = c.request_transfer(
        Chain::BitcoinTestnet4,
        Asset::Native,
        BTC_DEST.to_string(),
        U128(1_000),
        evm_params(),
        "mismatch".to_string(),
    );
}

#[test]
#[should_panic(expected = "compressed secp256k1 public key")]
fn a_malformed_btc_key_cannot_be_registered() {
    let mut c = btc_setup(false);
    ctx(OWNER, pk(0), at_utc(12, 0));
    c.set_agent_btc_pubkey(pk(1), "04".to_string() + &"11".repeat(64));
}

#[test]
#[should_panic(expected = "no keyring registered for this account")]
fn a_non_owner_cannot_register_a_btc_key() {
    let mut c = btc_setup(false);
    ctx("stranger.testnet", pk(0), at_utc(12, 0));
    c.set_agent_btc_pubkey(pk(1), BTC_PUBKEY.to_string());
}

#[test]
fn an_erc20_asset_is_rejected_on_bitcoin() {
    let mut c = btc_setup(true);
    ctx("agent-host.testnet", pk(1), at_utc(12, 0));
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        c.request_transfer(
            Chain::BitcoinTestnet4,
            Asset::Erc20 {
                token: "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".to_string(),
            },
            BTC_DEST.to_string(),
            U128(1_000),
            btc_params(1_000),
            "token-on-btc".to_string(),
        )
    }));
    assert!(result.is_err(), "a token cannot exist on Bitcoin");
}
